nextflow_process {

    name "Test Process PROOVFRAME_MAP"
    script "../main.nf"
    process "PROOVFRAME_MAP"

    tag "modules"
    tag "modules_nfcore"
    tag "proovframe"
    tag "proovframe/map"

    test("sarscov2 - provided db") {

        when {
            process {
                """
                input[0] = [
                    [ id:'fa' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                input[1] = [
                    [ id:'fa' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome.fasta', checkIfExists: true)
                ]
                input[2] = [
                    [ id:'fa' ],
                    file(params.modules_testdata_base_path + 'proteomics/database/UP000005640_9606.dmnd', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert path(process.out.tsv[0][1]).text.contains('MT192765.1	sp|Q460N5|PAR14_HUMAN	28.4	176	105	5	3424	3918	818	983') },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("sarscov2 - provided faa") {

        when {
            process {
                """
                input[0] = [
                    [ id:'fa' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                input[1] = [
                    [ id:'fa' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome.fasta', checkIfExists: true)
                ]
                input[2] = [[:], []]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert path(process.out.tsv[0][1]).text.contains('MT192765.1	ENSSASP00005000002.1	100.0	7096	1	0	259	21545	1') },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("sarscov2 - tsv - stub") {
        options '-stub'
        when {
            process {
                """
                input[0] = [
                    [ id:'test2' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                input[1] = [
                    [ id:'fa' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome.fasta', checkIfExists: true)
                ]
                input[2] = [
                    [ id:'fa' ],
                    file(params.modules_testdata_base_path + 'proteomics/database/UP000005640_9606.dmnd', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

